"""The run folder writer (AD-06)."""

import dataclasses
import json
from collections.abc import Mapping
from datetime import datetime
from pathlib import Path
from typing import Literal, TypeGuard, get_args

import numpy as np
import torch

from rllab.core.types import Box, Discrete, EpisodeResult, RunConfig, WorldSpec
from rllab.runlog.types import Checkpoint, EvalPoint, Failure, RunExistsError, RunRecord

Status = Literal["running", "finished", "incomplete", "failed"]
ACTION_KINDS: dict[type, str] = {Discrete: "discrete", Box: "box"}


def _is_status(status: str) -> TypeGuard[Status]:
    return status in get_args(Status)


def to_json(value: object) -> object:
    """The JSON form of a run-folder value: dataclasses as objects of their fields (`Discrete`
    and `Box` add `"kind"`), tuples as lists, a `Path` or `datetime` as a string."""
    if dataclasses.is_dataclass(value) and not isinstance(value, type):
        out = {f.name: to_json(getattr(value, f.name)) for f in dataclasses.fields(value)}
        kind = ACTION_KINDS.get(type(value))
        return {"kind": kind, **out} if kind else out
    if isinstance(value, Mapping):
        return {str(k): to_json(v) for k, v in value.items()}
    if isinstance(value, (tuple, list)):
        return [to_json(v) for v in value]
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, np.generic):
        return value.item()
    return value


class RunWriter:
    """Writes `runs/<world>/<variant>/<name>/`; `RunExistsError` if that folder exists."""

    def __init__(self, root: Path, config: RunConfig, spec: WorldSpec) -> None:
        self.path = root / config.world / config.variant / config.name
        self.path.parent.mkdir(parents=True, exist_ok=True)
        try:
            self.path.mkdir()
        except FileExistsError:
            raise RunExistsError(self.path) from None
        (self.path / "checkpoints").mkdir()
        self._config, self._spec = config, spec
        self._started = datetime.now()
        self._episodes = (self.path / "episodes.jsonl").open("a", encoding="utf-8")
        self._evals = (self.path / "evals.jsonl").open("a", encoding="utf-8")
        self._write_record(self._record(None, "running", None))

    def episode(self, result: EpisodeResult) -> None:
        self._episodes.write(json.dumps(to_json(result)) + "\n")

    def eval(self, point: EvalPoint) -> None:
        """Append `point` and flush every log."""
        self._evals.write(json.dumps(to_json(point)) + "\n")
        self._episodes.flush()
        self._evals.flush()

    def checkpoint(self, pct: int, step: int, state: Mapping[str, dict[str, object]]) -> Checkpoint:
        """Save `checkpoints/ckpt_<pct>.pt`: spec and method configs in JSON form, and state."""
        ckpt = Checkpoint(
            self._config.name,
            pct,
            step,
            self._spec,
            dict(self._config.methods),
            dict(state),
            self.path / "checkpoints" / f"ckpt_{pct}.pt",
        )
        saved = {
            "run": ckpt.run,
            "pct": pct,
            "step": step,
            "spec": to_json(ckpt.spec),
            "methods": to_json(ckpt.methods),
            "state": ckpt.state,
        }
        torch.save(saved, ckpt.path)
        return ckpt

    def close(self, status: str, failure: Failure | None = None) -> RunRecord:
        """Flush and close the logs, then record `status` (and `failure`) with the end time."""
        if not _is_status(status) or status == "running":
            raise ValueError(f"cannot close a run as {status!r}")
        self._episodes.close()
        self._evals.close()
        record = self._record(datetime.now(), status, failure)
        self._write_record(record)
        return record

    def _record(self, ended: datetime | None, status: Status, failure: Failure | None) -> RunRecord:
        return RunRecord(self._config, self._spec, self._started, ended, status, failure, self.path)

    def _write_record(self, record: RunRecord) -> None:
        """Replace `run.json` atomically: write a temporary file, then rename it over."""
        tmp = self.path / "run.json.tmp"
        tmp.write_text(json.dumps(to_json(record), indent=1) + "\n", encoding="utf-8")
        tmp.replace(self.path / "run.json")

