"""The training loop (PL-02 step 8)."""

import copy
from collections.abc import Iterator, Mapping
from itertools import islice
from pathlib import Path

import numpy as np

from rllab.core.episode import play_episode
from rllab.core.types import EVAL_SEEDS, Array, EpisodeResult, Step, World
from rllab.methods.types import Learner, Transition
from rllab.runlog.types import EvalPoint, RunRecord
from rllab.runlog.writer import RunWriter
from rllab.train.types import RunConfig

TRAIN_SEEDS_END = 1_000_000  # training episode seeds come from [0, 10⁶) (AD-05)
EVAL_EVERY_PCT = 5
CHECKPOINT_EVERY_PCT = 10


def train_loop(
    world: World, learners: Mapping[str, Learner], config: RunConfig, root: Path
) -> RunRecord:
    """Exactly `budget` world steps, written through `runlog.RunWriter`, with checkpoints at
    every 10% and evaluations on `EVAL_SEEDS` at every 5%."""
    writer = RunWriter(root, config, world.spec)
    eval_world = copy.deepcopy(world)  # evaluation never disturbs the training episode
    steps = training_steps(world, learners, writer, config.seed)
    done = 0
    for pct in range(0, 101, EVAL_EVERY_PCT):
        target = pct * config.budget // 100
        for _ in islice(steps, target - done):
            pass
        done = target
        writer.eval(evaluate(eval_world, learners, done))
        if pct % CHECKPOINT_EVERY_PCT == 0:
            writer.checkpoint(pct, done, {team: lr.state_dict() for team, lr in learners.items()})
    return writer.close("finished")


def training_steps(
    world: World, learners: Mapping[str, Learner], writer: RunWriter, seed: int
) -> Iterator[None]:
    """Play training episodes without end, one world step per item, each team's learner acting
    and observing; every finished episode goes to `writer`.

    The run seed's spawned children: 0 seeds the learners (`train.setup`), 1 exploration and
    2 the episode seeds (AD-05)."""
    explore = np.random.default_rng(np.random.SeedSequence(seed, spawn_key=(1,)))
    episode_seeds = np.random.default_rng(np.random.SeedSequence(seed, spawn_key=(2,)))
    spec = world.spec
    while True:
        last = world.reset(int(episode_seeds.integers(0, TRAIN_SEEDS_END)))
        for t in range(1, spec.max_steps + 1):
            team_actions = {
                team.name: learners[team.name].act(last.obs[list(team.agents)], explore)
                for team in spec.teams
            }
            nxt = world.step(join_actions(world, team_actions))
            truncated = nxt.truncated or (t == spec.max_steps and not nxt.done)
            for team in spec.teams:
                rows = list(team.agents)
                learners[team.name].observe(
                    Transition(
                        obs=last.obs[rows],
                        actions=team_actions[team.name],
                        rewards=nxt.rewards[rows],
                        next_obs=nxt.obs[rows],
                        done=nxt.done,
                        truncated=truncated,
                        active=nxt.active[rows],
                    )
                )
            last = nxt
            if nxt.done or truncated:
                writer.episode(world.result())
            yield None
            if nxt.done or truncated:
                break


def join_actions(world: World, team_actions: Mapping[str, Array]) -> Array:
    """One action row per agent, from each team's rows in `TeamSpec.agents` order."""
    rows: dict[int, Array] = {}
    for team in world.spec.teams:
        rows.update(zip(team.agents, team_actions[team.name], strict=True))
    return np.stack([rows[i] for i in range(len(world.spec.agents))])


def evaluate(world: World, learners: Mapping[str, Learner], step: int) -> EvalPoint:
    """Mean scores per team and mean measures over one episode per `EVAL_SEEDS` seed, played by
    each learner's frozen policy."""
    policies = {team: learner.policy() for team, learner in learners.items()}
    results = [play_episode(world, policies, seed).result for seed in EVAL_SEEDS]
    return EvalPoint(
        step,
        mean_by_name([r.scores for r in results]),
        mean_by_name([r.measures for r in results]),
    )


def mean_by_name(values: list[Mapping[str, float]]) -> dict[str, float]:
    """The mean of each name's values across `values`."""
    return {name: float(np.mean([v[name] for v in values])) for name in values[0]}


def _unused(_: EpisodeResult, __: Step) -> None:
    pass

